        let depth = 1;
        let i = m.index + m[0].length;
        for (; i < src.length && depth > 0; i += 1) {
            if (src[i] === "{") depth += 1;
            else if (src[i] === "}") depth -= 1;
        }
        ranges.push([m.index, i]);
    }
    return ranges;
};

