@import "tailwindcss" source("../demo");
/* The demo dogfoods the library source (it `@import`s
   `src/styles/index.css` directly for HMR), so it must also CONTENT-SCAN the
   library component SOURCE for the utility classes those components render — the
   functional/sizing utilities (`size-(--search-icon-size)`, `h-(--switch-track-h)`,
   `controlSizeClass` data seam) that the published library ships via
   `emitComponentUtilities` (vite.style-assets.ts, dist-only) but that the DEMO dev
   build would otherwise never generate (the `source("../demo")` scope stops at the
   demo tree). Scoped to the `.vue` SFCs + the size/variant `.ts` helpers and AWAY
   from `composables/` + `*.glsl.ts`/`*.wgsl.ts` so the dev candidate-extractor never
   trips on a shader template literal (the `Missing opening (` trap index.css §EMISSION
   narrates).

   THE `_shared` GLOB IS RECURSIVE, and the one character is load-bearing: the
   single-level form never reached `_shared/menu/rowClass.ts`, so the Select and
   Command indicator gutter had no rule in the demo at all. Widening `_shared` to
   a recursive glob is safe; blanket-widening the whole `components` tree the same
   way is NOT — the shader template literals named just above live under
   `components/blob/shaders/`, and `_shared` contains no shader file.
   (Written without a glob star adjacent to a slash on purpose: that two-character
   sequence closes a CSS comment, and Tailwind then reads the rest of this
   paragraph as a declaration.) */
@source "../src/components/**/*.vue";
@source "../src/components/_shared/**/*.ts";
@source "../src/components/**/*Variants.ts";
/* Scan the CVA maps in each component's index.ts too. A
   component's cva() variant/tone map lives in index.ts, NOT the .vue render, so
   the class strings it composes (text-destructive-foreground, the four-state
   destructive tone fill bg-destructive + the hover/active/aria-pressed opacity
   rungs) are UNREACHED by the .vue scan above. Without this glob the demo build
   never generates the BARE .text-destructive-foreground rule, so a shipped
   destructive-tone Button label falls to the inherited ink over the red fill
   (the A11Y-1 3.57:1 fail). The index.ts scope is the CVA-map convention (KEEP
   away from composables/useX helpers + shaders so the dev candidate-extractor
   never trips a template-literal — no glsl/wgsl template lives under ui). The
   published library ships these same rules for a BARE consumer via
   emitComponentUtilities (dist components.css); this is the demo's own scan. */
@source "../src/components/**/index.ts";
@import "tw-animate-css";
/* The demo's development cascade imports the complete library source styles
   (the full index.css) for HMR simplicity; this is the byte-complete union the
   `@mkbabb/glass-ui/styles` export resolves. The critical/deferred SPLIT is a
   PUBLISHED-dist concern (publishStyleAssets emits dist/styles/{critical,
   deferred}.css off src/styles/critical-partition.mjs) measured under the
   production preview; the loader recipe lives in index.html's <head>. The demo
   does not fork a second source critical/deferred block. */
@import "../src/styles/index.css";
@import "./chassis/hero/story-hero.css";
/* THE ONE LAYOUT — the ladder, the four measures, the article law, the cel field.
   Imported AFTER story-hero.css so the chassis rungs win over anything the hero
   sheet still declares on `:root`. */
@import "./chassis/layout.css";
/* The retired liquid-morph, fission, Siri, and orientation-goo demo surfaces
   (`liquid-morph.css`, `liquid-playground`, `dock-gallery`, `morph-showcase`,
   `siri-island`) are DEFINITION-ABSENT (the whole goo-dock spectacle retired
   decided-terminal; clean break, no alias). */

@variant dark (&:where(.dark, .dark *));

/*
 * The /motion family has one coherent purple identity, expressed
 * as a DEMO-LOCAL token (never a library token — presets-in-consumers). The accent
 * is the EXISTING glass-ui `--viz-legendre` violet (the page-local twin of the
 * keyframes ppmycota brand color), so the motion plots / driven dots / spring block
 * read one violet event, not warm-red, with zero library-token edit.
 *
 * `--ppmycota` is a DEMO-LOCAL keyframes-identity nod ONLY — it is referenced here
 * for documentation parity with the keyframes demo and never enters `src/styles/`.
 */
:root {
    --motion-accent: var(--viz-legendre);
    /* the keyframes consumer brand color — demo-local reference, never a lib token */
    --ppmycota: hsl(248 88% 71%);
}

html {
    background: var(--background);
}

